import sys, time

def solve(N,P):
    maxE=N*(N-1)//2
    # comb modulo P up to N
    C=[[0]*(N+1) for _ in range(N+1)]
    for i in range(N+1):
        C[i][0]=C[i][i]=1%P
        for j in range(1,i):
            C[i][j]=(C[i-1][j-1]+C[i-1][j])%P
    # factor terms: (a,b) -> list (qadd, coeff)
    fac={}
    for a in range(1,N+1):
        for b in range(1,N+1):
            terms=[]
            base=b*(b-1)//2
            for j in range(b+1):
                q=a*(b-j)+base
                coef=C[b][j]
                if j&1: coef=(-coef)%P
                terms.append((q,coef))
            fac[(a,b)]=terms
    target=N//2
    # dp key -> dict q:coef
    dp={(1,1,1,1):{0:1}}
