                    dest=ndp
                w=C[rem][b]
                terms=fac[(a,b)]
                key=(b,nt,ne,1-par) if nt<N else None
                if nt<N:
                    d=dest.get(key)
                    if d is None:
                        d={}
                        dest[key]=d
                else:
                    d=dest
                for q,co in poly.items():
                    for qa,ca in terms:
                        qq=q+qa
                        d[qq]=(d.get(qq,0)+co*ca%P*w)%P
        dp=ndp
    print('rounds',rounds,'states final poly',len(final),'time',time.time()-t0,file=sys.stderr)
    out=[]
    for M in range(N-1,maxE+1):
        s=0
        for q,co in final.items():
            if q>=M:
                s=(s+co*C[q][M])%P
        out.append(s%P)
    return out

if __name__=='__main__':
    N=int(sys.argv[1]); P=int(sys.argv[2])
    print(*solve(N,P))
